import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.Cm6XCzck.js";const p=JSON.parse('{"title":"Research Runtime Center V5.0","description":"","frontmatter":{"title":"Research Runtime Center V5.0","outline":"deep"},"headers":[],"relativePath":"zh/runtime/v5.md","filePath":"zh/runtime/v5.md","lastUpdated":1786503324000}'),n={name:"zh/runtime/v5.md"};function o(l,e,d,s,c,u){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="research-runtime-center-v5-0" tabindex="-1">Research Runtime Center V5.0 <a class="header-anchor" href="#research-runtime-center-v5-0" aria-label="Permalink to &quot;Research Runtime Center V5.0&quot;">​</a></h1><p><strong>状态：</strong> 架构冻结<br><strong>调度器：</strong> Research Runtime Scheduler V3.0<br><strong>生效日期：</strong> 2026-08-05<br><strong>时区：</strong> Asia/Shanghai</p><h2 id="为什么必须升级到-v5" tabindex="-1">为什么必须升级到 V5 <a class="header-anchor" href="#为什么必须升级到-v5" aria-label="Permalink to &quot;为什么必须升级到 V5&quot;">​</a></h2><p>V4 把长期 Research Program 与 Daily 生产线混在一起。09:00 Engine 先推进长期对象，而当天新选题到 10:00 才产生，导致新对象无法在 15:00 Production 之前完成 Reading 与 Analysis。</p><p>V5 彻底消除这个结构冲突。</p><h2 id="四套独立-runtime" tabindex="-1">四套独立 Runtime <a class="header-anchor" href="#四套独立-runtime" aria-label="Permalink to &quot;四套独立 Runtime&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Runtime</th><th>职责</th><th>输入</th><th>输出</th></tr></thead><tbody><tr><td>Daily</td><td>当天发现、研究、生产、发布</td><td>当天信号</td><td>Released Daily Research</td></tr><tr><td>Weekly</td><td>可独立阅读的 AI Research Brief</td><td>过去七天已验证 Daily Research</td><td>重要变化、相互联系、证据与争议、可支持的判断、开放问题</td></tr><tr><td>Academic</td><td>正式学术观察</td><td>Paper、Benchmark、Specification、Institution</td><td>Academic Observation</td></tr><tr><td>Program</td><td>长期受治理研究</td><td>独立 Program Queue</td><td>Program 状态转换与 Program Publication</td></tr></tbody></table><p>四套体系分别维护 Record、Queue 与运行时间线。</p><h2 id="daily-runtime" tabindex="-1">Daily Runtime <a class="header-anchor" href="#daily-runtime" aria-label="Permalink to &quot;Daily Runtime&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>09:00 Discovery → Signal Pool</span></span>
<span class="line"><span>10:00 Queue → Today&#39;s Research Plan</span></span>
<span class="line"><span>11:00 Reading → Reading Result</span></span>
<span class="line"><span>13:00 Analysis → Research Object</span></span>
<span class="line"><span>15:00 Production → Publication Candidate</span></span>
<span class="line"><span>20:00 Publication → GitHub + Website + Commit Verify + Release</span></span></code></pre></div><p>Daily 的三个栏目是 Digital Employee、Industry Architecture、Open-source Engineering。每天每个栏目必须明确为 <code>Selected</code> 或 <code>No Selection</code>。</p><h2 id="阶段权威" tabindex="-1">阶段权威 <a class="header-anchor" href="#阶段权威" aria-label="Permalink to &quot;阶段权威&quot;">​</a></h2><ul><li>Discovery 执行三条 Research Intelligence Profile；</li><li>Queue 只执行三栏选题；</li><li>Reading 执行 Skill 03；</li><li>Analysis 执行 Skill 04；</li><li>Production 执行 Skill 05–08；</li><li>Publication 只负责发版。</li></ul><p>自 2026-08-12 起，Analysis 与 Production 同时执行 Editorial Architecture V2：研究问题驱动、可扩展文章类型、动态正文模块、证据身份、研究独立性、六项编辑 Gate，以及可选且独立改写的 Community Edition。V5 Runtime 拓扑与阶段顺序保持不变。</p><p>Production 唯一合法输入是 <code>Research Object</code>；Publication 唯一合法输入是完整 <code>Publication Candidate</code>。</p><h2 id="独立调度" tabindex="-1">独立调度 <a class="header-anchor" href="#独立调度" aria-label="Permalink to &quot;独立调度&quot;">​</a></h2><ul><li>Weekly Runtime：周日 20:30；</li><li>Academic Runtime：周三 16:00；</li><li>Research Program Runtime：周一 12:00。</li></ul><p>Program 覆盖 TMPA、FCoP、CodeFlowMu、Digital Employee、Research Operating System，永远不进入 Daily Runtime。</p><h2 id="runtime-record" tabindex="-1">Runtime Record <a class="header-anchor" href="#runtime-record" aria-label="Permalink to &quot;Runtime Record&quot;">​</a></h2><p>V5 分别在以下目录创建 JSON Record：</p><ul><li><code>research/runtime/records/daily/</code></li><li><code>research/runtime/records/weekly/</code></li><li><code>research/runtime/records/academic/</code></li><li><code>research/runtime/records/program/</code></li></ul><p>所有终态班次必须汇报 Input、Work Result、Output、Next、Metrics、Evidence、Artifacts。</p><h2 id="github-actions-与-chatgpt-worker" tabindex="-1">GitHub Actions 与 ChatGPT Worker <a class="header-anchor" href="#github-actions-与-chatgpt-worker" aria-label="Permalink to &quot;GitHub Actions 与 ChatGPT Worker&quot;">​</a></h2><p>GitHub Actions 只负责打开执行槽；ChatGPT Worker 执行真实研究。执行槽在 Worker 写入合法结果之前保持 <code>Waiting</code>。Scheduler 禁止制造 <code>Completed</code>。</p><h2 id="冻结规则" tabindex="-1">冻结规则 <a class="header-anchor" href="#冻结规则" aria-label="Permalink to &quot;冻结规则&quot;">​</a></h2><p>V5.0 完成后，四套 Runtime 的边界、Daily 六阶段和 Scheduler V3 的九个任务身份冻结。后续工作只做优化：来源质量、Worker 效率、指标、页面体验、证据质量与出版质量。</p>`,26)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
